function getCategoryById(id) {
  return CATEGORIES.find((c) => c.id === id);
}

function getProductById(id) {
  return PRODUCTS.find((p) => p.id === Number(id));
}

/* Пастельный фон + акцентный цвет иконки для карточки товара, без реальных фото. */
function categoryColors(categoryId) {
  const idx = CATEGORIES.findIndex((c) => c.id === categoryId);
  const hue = Math.round((idx >= 0 ? idx : 0) * (360 / CATEGORIES.length));
  return {
    bg: `hsl(${hue}, 60%, 94%)`,
    fg: `hsl(${hue}, 45%, 40%)`
  };
}

function currencyLabel(currency) {
  return currency === "USD" ? "$" : "сом";
}

function formatPrice(value, currency) {
  const formatted = new Intl.NumberFormat("ru-RU").format(value);
  return currency === "USD" ? `$${formatted}` : `${formatted} сом`;
}

function productThumbHTML(product) {
  const cat = getCategoryById(product.categoryId);
  const colors = categoryColors(product.categoryId);
  if (product.image) {
    return `<div class="product-thumb product-thumb-photo" style="background:${colors.bg}">
      <img src="${product.image}" alt="${product.name}" loading="lazy" onerror="this.closest('.product-thumb').classList.add('img-error');this.remove();">
      <span class="thumb-fallback">${cat ? cat.icon : "📦"}</span>
    </div>`;
  }
  return `<div class="product-thumb" style="background:${colors.bg};color:${colors.fg}">
    <span>${cat ? cat.icon : "📦"}</span>
  </div>`;
}

function renderProductCard(product) {
  const priceHTML = product.oldPrice
    ? `<span class="price-old">${formatPrice(product.oldPrice, product.currency)}</span> <span class="price">${formatPrice(product.price, product.currency)}</span>`
    : `<span class="price">${formatPrice(product.price, product.currency)}</span>`;

  return `
  <article class="product-card" data-id="${product.id}">
    <a class="product-thumb-link" href="product.html?id=${product.id}">
      ${productThumbHTML(product)}
    </a>
    <div class="product-body">
      <a class="product-title" href="product.html?id=${product.id}">${product.name}</a>
      <div class="product-price">${priceHTML}<span class="unit">/ ${product.unit}</span></div>
      <button class="btn btn-primary btn-add-cart" data-id="${product.id}">В корзину</button>
    </div>
  </article>`;
}
